"""Generated by the NL to Flow Diagram Encoder Pipeline."""

firstNum = 0

secondNum = 0

errorString = "That's Not a Valid Number, Please Try Again!"

loop = True

while (loop == True):
    firstNum = input('Enter First Number: ')
    try:
        firstNum = int(firstNum)
        if (firstNum < 0):
            firstNum = abs(firstNum)
        loop = False
    except Exception:
        print(errorString)

loop = True

while (loop == True):
    secondNum = input('Enter Second Number: ')
    try:
        secondNum = int(secondNum)
        if (secondNum < 0):
            secondNum = abs(secondNum)
        loop = False
    except Exception:
        print(errorString)

def gcd(first, second):
    remainder = (first % second)
    while (remainder != 0):
        first = second
        second = remainder
        remainder = (first % second)
    return second

if (firstNum > secondNum):
    a = firstNum
    b = secondNum
else:
    a = secondNum
    b = firstNum

gcd_result = gcd(a, b)

print(f'GCD = {gcd_result}')
